        for dy in range(-3, 4):
            for dx in range(-3, 4):
                if dy == 0 and dx == 0:
                    continue
                # Test if shifting by (dy, dx) produces the output
                shifted = np.zeros_like(input_grid)
                for i in range(input_grid.shape[0]):
